from pathlib import Path
D=Path('chapters/E05')
def edit(file,changes):
 p=D/file;s=p.read_text()
 for old,new in changes:
  assert s.count(old)==1,(file,old[:100],s.count(old));s=s.replace(old,new)
 p.write_text(s)
